def solve(inputs: dict) -> float:
    n = inputs['n']
    k = inputs['k']

    # Josephus problem: simulate the elimination
    people = list(range(1, n + 1))  # positions 1 to n
    current_index = 0

    while len(people) > 1:
        # Every k-th person is eliminated
        current_index = (current_index + k - 1) % len(people)
        people.pop(current_index)
        # After removal, current_index points to the next person
        if current_index >= len(people) and len(people) > 0:
            current_index = 0

    return float(people[0])
